import MoneroKeyImage from "../../daemon/model/MoneroKeyImage";
/**
 * Models results from exporting signed key images.
 */
export default class MoneroKeyImageExportResult {
    constructor(result) {
        Object.assign(this, result);
        if (this.keyImages)
            this.keyImages = this.keyImages.map(keyImage => keyImage instanceof MoneroKeyImage ? keyImage : new MoneroKeyImage(keyImage));
    }
    toJson() {
        let json = Object.assign({}, this);
        if (this.getKeyImages() !== undefined)
            json.keyImages = this.getKeyImages().map(keyImage => keyImage.toJson());
        return json;
    }
    getOffset() {
        return this.offset;
    }
    setOffset(offset) {
        this.offset = offset;
        return this;
    }
    getKeyImages() {
        return this.keyImages;
    }
    setKeyImages(keyImages) {
        this.keyImages = keyImages;
        return this;
    }
}
